function ScoreForm({
	ranking,
	onUpdateRanking,
	player1Name,
	player2Name,
	onSelectPlayer1,
	onSelectPlayer2,
	player1Score,
	player2Score,
	onAddP1Score,
	onAddP2Score,
	onAddScore,
}) {
	// Handle submit form
	function handleSubmit(e) {
		e.preventDefault();

		// Build the new result, and add it into the scoreBoard state/table.
		const newResult = {
			id: Date.now(),
			homeTeam: player1Name,
			awayTeam: player2Name,
			result: player1Score + " : " + player2Score,
		};
		if (player1Name && player2Name) {
			onAddScore(newResult);
		} else {
			alert("Select both teams, please.");
		}
		if (newResult) {
			if (player1Score > player2Score) {
				console.log("Player1 scored more goals");
			} else if (player2Score > player1Score) {
				console.log("Player2 scored more goals!");
			} else {
				console.log("Tie! No winner today.");
			}
		} else {
			console.log("Nothing to update!");
		}
	}

	const playerObj = ranking.map((player) => player);
	const {
		id,
		teamName,
		points,
		wins,
		draws,
		losses,
		goalsFor,
		goalsAgainst,
		goalDifference,
	} = playerObj;

	return (
		<div className="scores">
			<form onSubmit={handleSubmit}>
				<span>
					<select
						defaultValue={"home"}
						value={teamName}
						onChange={(e) => onSelectPlayer1(e.target.value)}
						required
					>
						<option value="home" disabled>
							Home Team
						</option>
						<option value={playerObj[0].teamName}>
							{playerObj[0].teamName}
						</option>
						<option value={playerObj[1].teamName}>
							{playerObj[1].teamName}
						</option>
						<option value={playerObj[2].teamName}>
							{playerObj[2].teamName}
						</option>
					</select>
					<input
						type="number"
						value={player1Score}
						onChange={(e) => onAddP1Score(e.target.value)}
						required
					/>
				</span>
				:
				<span>
					<select
						defaultValue={"away"}
						value={teamName}
						onChange={(e) => onSelectPlayer2(e.target.value)}
						required
					>
						<option value="away" disabled>
							Away Team
						</option>
						<option value={playerObj[0].teamName}>
							{playerObj[0].teamName}
						</option>
						<option value={playerObj[1].teamName}>
							{playerObj[1].teamName}
						</option>
						<option value={playerObj[2].teamName}>
							{playerObj[2].teamName}
						</option>
					</select>
					<input
						type="number"
						value={player2Score}
						onChange={(e) => onAddP2Score(e.target.value)}
						required
					/>
				</span>
				<button>Add</button>
			</form>
		</div>
	);
}
export default ScoreForm;
